def greedy_pack(order,W,H,align='left',score='yx'):
    rects=[]
    for n in order:
        w0,h0=pieces[n][1],pieces[n][0]
        candidates=[]
        for y in range(H-h0+1):
            for x in range(W-w0+1):
                if all(x+w0<=xx or xx+ww<=x or y+h0<=yy or yy+hh<=y for nn,yy,xx,hh,ww in rects):
                    if score=='yx':sc=(y,x if align=='left' else -x)
                    elif score=='xy':sc=(x,y)
                    candidates.append((sc,y,x))
        if not candidates:return None
        _,y,x=min(candidates)
        rects.append((n,y,x,h0,w0))
    return rects
